-- BahariMRV initial schema (SQLite). Mirrors the PostgreSQL migration with
-- SQLite affinities: identifiers, timestamps and fixed-precision decimals are TEXT
-- so decimal strings and RFC3339 timestamps round-trip without numeric coercion.
CREATE TABLE users (id TEXT PRIMARY KEY, email TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, display_name TEXT NOT NULL, phone TEXT NOT NULL DEFAULT '', role TEXT NOT NULL, status TEXT NOT NULL, created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL);
CREATE INDEX idx_users_role ON users(role); CREATE INDEX idx_users_status ON users(status);
CREATE TABLE key_references (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), provider TEXT NOT NULL, external_ref TEXT NOT NULL, wrapped_key BLOB NOT NULL, nonce BLOB NOT NULL, public_key BLOB NOT NULL, created_at TIMESTAMP NOT NULL, rotated_at TIMESTAMP, revoked_at TIMESTAMP);
CREATE TABLE identity_provisions (id TEXT PRIMARY KEY, user_id TEXT NOT NULL UNIQUE REFERENCES users(id), state TEXT NOT NULL, did TEXT NOT NULL DEFAULT '', did_document_ref TEXT NOT NULL DEFAULT '', address TEXT NOT NULL DEFAULT '', key_reference_id TEXT NOT NULL DEFAULT '', provision_tx_ref TEXT NOT NULL DEFAULT '', network TEXT NOT NULL, attempts INTEGER NOT NULL DEFAULT 0, last_error TEXT NOT NULL DEFAULT '', created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL, activated_at TIMESTAMP, last_provisioned_at TIMESTAMP);
CREATE INDEX idx_identity_provisions_state ON identity_provisions(state);
CREATE TABLE local_sessions (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), token_hash TEXT NOT NULL UNIQUE, expires_at TIMESTAMP NOT NULL, revoked_at TIMESTAMP, created_at TIMESTAMP NOT NULL);
CREATE INDEX idx_local_sessions_user_id ON local_sessions(user_id); CREATE INDEX idx_local_sessions_expires_at ON local_sessions(expires_at);
CREATE TABLE external_identities (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), issuer TEXT NOT NULL, subject TEXT NOT NULL, revoked_at TIMESTAMP, created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL, CONSTRAINT idx_external_subject UNIQUE(issuer,subject), CONSTRAINT idx_external_user_issuer UNIQUE(user_id,issuer));
CREATE TABLE federated_grants (id TEXT PRIMARY KEY, external_identity_id TEXT NOT NULL REFERENCES external_identities(id), token_hash TEXT NOT NULL UNIQUE, scope TEXT NOT NULL, expires_at TIMESTAMP NOT NULL, revoked_at TIMESTAMP, created_at TIMESTAMP NOT NULL); CREATE INDEX idx_federated_grants_external_identity_id ON federated_grants(external_identity_id);
CREATE TABLE oidc_clients (id TEXT PRIMARY KEY, secret_hash TEXT NOT NULL DEFAULT '', redirect_uris TEXT NOT NULL, allowed_scopes TEXT NOT NULL, disabled INTEGER NOT NULL DEFAULT 0, created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL);
CREATE TABLE oauth_grants (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), client_id TEXT NOT NULL REFERENCES oidc_clients(id), scope TEXT NOT NULL, revoked_at TIMESTAMP, created_at TIMESTAMP NOT NULL);
CREATE INDEX idx_oauth_grants_user_id ON oauth_grants(user_id); CREATE INDEX idx_oauth_grants_client_id ON oauth_grants(client_id);
CREATE TABLE authorization_codes (id TEXT PRIMARY KEY, code_hash TEXT NOT NULL UNIQUE, user_id TEXT NOT NULL REFERENCES users(id), client_id TEXT NOT NULL REFERENCES oidc_clients(id), grant_id TEXT NOT NULL REFERENCES oauth_grants(id), redirect_uri TEXT NOT NULL, scope TEXT NOT NULL, nonce TEXT NOT NULL, code_challenge TEXT NOT NULL, expires_at TIMESTAMP NOT NULL, used_at TIMESTAMP, created_at TIMESTAMP NOT NULL);
CREATE INDEX idx_authorization_codes_user_id ON authorization_codes(user_id); CREATE INDEX idx_authorization_codes_client_id ON authorization_codes(client_id); CREATE INDEX idx_authorization_codes_expires_at ON authorization_codes(expires_at);
CREATE TABLE access_tokens (id TEXT PRIMARY KEY, token_hash TEXT NOT NULL UNIQUE, grant_id TEXT NOT NULL REFERENCES oauth_grants(id), user_id TEXT NOT NULL REFERENCES users(id), client_id TEXT NOT NULL REFERENCES oidc_clients(id), scope TEXT NOT NULL, expires_at TIMESTAMP NOT NULL, created_at TIMESTAMP NOT NULL);
CREATE INDEX idx_access_tokens_grant_id ON access_tokens(grant_id); CREATE INDEX idx_access_tokens_user_id ON access_tokens(user_id); CREATE INDEX idx_access_tokens_expires_at ON access_tokens(expires_at);
CREATE TABLE methodologies (id TEXT PRIMARY KEY, code TEXT NOT NULL UNIQUE, name TEXT NOT NULL, version TEXT NOT NULL, required_evidence TEXT NOT NULL, estimation TEXT NOT NULL DEFAULT '{}', created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL);
CREATE TABLE conservation_projects (id TEXT PRIMARY KEY, name TEXT NOT NULL, manager_id TEXT NOT NULL REFERENCES users(id), methodology_id TEXT NOT NULL REFERENCES methodologies(id), status TEXT NOT NULL, community_share_bps INTEGER NOT NULL CHECK(community_share_bps >= 0 AND community_share_bps <= 10000), sandbox_demo INTEGER NOT NULL DEFAULT 0, created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL);
CREATE INDEX idx_conservation_projects_manager_id ON conservation_projects(manager_id);
CREATE TABLE sites (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES conservation_projects(id), name TEXT NOT NULL, created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL); CREATE INDEX idx_sites_project_id ON sites(project_id);
CREATE TABLE plots (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES conservation_projects(id), site_id TEXT NOT NULL REFERENCES sites(id), code TEXT NOT NULL, latitude REAL NOT NULL, longitude REAL NOT NULL, area_hectares TEXT NOT NULL, assigned_monitor_id TEXT NOT NULL DEFAULT '', created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL, CONSTRAINT idx_site_plot UNIQUE(site_id,code)); CREATE INDEX idx_plots_project_id ON plots(project_id); CREATE INDEX idx_plots_assigned_monitor_id ON plots(assigned_monitor_id);
CREATE TABLE conservation_activities (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES conservation_projects(id), plot_id TEXT NOT NULL REFERENCES plots(id), manager_id TEXT NOT NULL REFERENCES users(id), activity_type TEXT NOT NULL, status TEXT NOT NULL, reporting_period_start TIMESTAMP NOT NULL, reporting_period_end TIMESTAMP NOT NULL, methodology_version TEXT NOT NULL, measurements TEXT NOT NULL DEFAULT '{}', current_event_id TEXT NOT NULL DEFAULT '', created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL);
CREATE INDEX idx_conservation_activities_project_id ON conservation_activities(project_id); CREATE INDEX idx_conservation_activities_plot_id ON conservation_activities(plot_id); CREATE INDEX idx_conservation_activities_status ON conservation_activities(status);
CREATE TABLE monitoring_records (id TEXT PRIMARY KEY, activity_id TEXT NOT NULL REFERENCES conservation_activities(id), monitor_id TEXT NOT NULL REFERENCES users(id), client_id TEXT NOT NULL, device_timestamp TIMESTAMP NOT NULL, server_receipt_time TIMESTAMP NOT NULL, methodology_version TEXT NOT NULL, schema_version TEXT NOT NULL, latitude REAL NOT NULL, longitude REAL NOT NULL, gps_accuracy_meters REAL NOT NULL, alive_count INTEGER NOT NULL, planted_count INTEGER NOT NULL, average_height_metres TEXT NOT NULL DEFAULT '', species TEXT NOT NULL DEFAULT '[]', attestation TEXT NOT NULL, attestation_hash TEXT NOT NULL, evidence_manifest TEXT NOT NULL DEFAULT '[]', content_commitment TEXT NOT NULL, signed INTEGER NOT NULL DEFAULT 0, version INTEGER NOT NULL DEFAULT 1, supersedes_id TEXT NOT NULL DEFAULT '', sync_status TEXT NOT NULL, created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL, CONSTRAINT idx_monitor_client UNIQUE(monitor_id,client_id));
CREATE INDEX idx_monitoring_records_activity_id ON monitoring_records(activity_id); CREATE INDEX idx_monitoring_records_monitor_id ON monitoring_records(monitor_id);
CREATE TABLE evidence_objects (id TEXT PRIMARY KEY, monitoring_record_id TEXT NOT NULL REFERENCES monitoring_records(id), kind TEXT NOT NULL, storage_uri TEXT NOT NULL, sha256 TEXT NOT NULL, media_type TEXT NOT NULL, access_class TEXT NOT NULL, captured_at TIMESTAMP NOT NULL, created_at TIMESTAMP NOT NULL); CREATE INDEX idx_evidence_objects_monitoring_record_id ON evidence_objects(monitoring_record_id);
CREATE TABLE satellite_observations (id TEXT PRIMARY KEY, activity_id TEXT NOT NULL REFERENCES conservation_activities(id), adapter_mode TEXT NOT NULL, status TEXT NOT NULL, scene_id TEXT NOT NULL DEFAULT '', acquired_at TIMESTAMP, processing_version TEXT NOT NULL DEFAULT '', result TEXT NOT NULL DEFAULT '{}', result_hash TEXT NOT NULL, created_at TIMESTAMP NOT NULL); CREATE INDEX idx_satellite_observations_activity_id ON satellite_observations(activity_id);
CREATE TABLE verification_requests (id TEXT PRIMARY KEY, activity_id TEXT NOT NULL REFERENCES conservation_activities(id), verifier_id TEXT NOT NULL REFERENCES users(id), status TEXT NOT NULL, requested_at TIMESTAMP NOT NULL, decided_at TIMESTAMP, created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL); CREATE INDEX idx_verification_requests_activity_id ON verification_requests(activity_id); CREATE INDEX idx_verification_requests_verifier_id ON verification_requests(verifier_id);
CREATE TABLE verifier_attestations (id TEXT PRIMARY KEY, request_id TEXT NOT NULL REFERENCES verification_requests(id), activity_id TEXT NOT NULL REFERENCES conservation_activities(id), verifier_id TEXT NOT NULL REFERENCES users(id), issuer_did TEXT NOT NULL, decision TEXT NOT NULL, statement TEXT NOT NULL DEFAULT '', attestation_hash TEXT NOT NULL, revoked_at TIMESTAMP, created_at TIMESTAMP NOT NULL); CREATE INDEX idx_verifier_attestations_activity_id ON verifier_attestations(activity_id);
CREATE TABLE provenance_events (id TEXT PRIMARY KEY, activity_id TEXT NOT NULL REFERENCES conservation_activities(id), claim_type TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, commitment TEXT NOT NULL, canonical_json TEXT NOT NULL DEFAULT '{}', previous_event_id TEXT NOT NULL DEFAULT '', issuer_did TEXT NOT NULL, status TEXT NOT NULL, network TEXT NOT NULL, transaction_ref TEXT NOT NULL DEFAULT '', object_id TEXT NOT NULL DEFAULT '', created_at TIMESTAMP NOT NULL, confirmed_at TIMESTAMP, CONSTRAINT idx_activity_claim_commitment UNIQUE(activity_id,claim_type,commitment)); CREATE INDEX idx_provenance_events_activity_id ON provenance_events(activity_id); CREATE INDEX idx_provenance_events_status ON provenance_events(status);
CREATE TABLE anchor_attempts (id TEXT PRIMARY KEY, provenance_event_id TEXT NOT NULL REFERENCES provenance_events(id), attempt INTEGER NOT NULL, status TEXT NOT NULL, transaction_ref TEXT NOT NULL DEFAULT '', error TEXT NOT NULL DEFAULT '', created_at TIMESTAMP NOT NULL); CREATE INDEX idx_anchor_attempts_provenance_event_id ON anchor_attempts(provenance_event_id);
CREATE TABLE corrections (id TEXT PRIMARY KEY, activity_id TEXT NOT NULL REFERENCES conservation_activities(id), previous_event_id TEXT NOT NULL REFERENCES provenance_events(id), superseding_event_id TEXT NOT NULL DEFAULT '', reason TEXT NOT NULL, requested_by TEXT NOT NULL REFERENCES users(id), created_at TIMESTAMP NOT NULL); CREATE INDEX idx_corrections_activity_id ON corrections(activity_id);
CREATE TABLE disputes (id TEXT PRIMARY KEY, activity_id TEXT NOT NULL REFERENCES conservation_activities(id), status TEXT NOT NULL, reason TEXT NOT NULL, resolved_at TIMESTAMP, created_at TIMESTAMP NOT NULL); CREATE INDEX idx_disputes_activity_id ON disputes(activity_id);
CREATE TABLE sync_actions (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), client_id TEXT NOT NULL, action_type TEXT NOT NULL, request_hash TEXT NOT NULL, status TEXT NOT NULL, response TEXT NOT NULL DEFAULT '{}', error TEXT NOT NULL DEFAULT '', resource_id TEXT NOT NULL DEFAULT '', created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL, CONSTRAINT idx_sync_user_client UNIQUE(user_id,client_id)); CREATE INDEX idx_sync_actions_status ON sync_actions(status);
CREATE TABLE audit_events (id TEXT PRIMARY KEY, user_id TEXT NOT NULL DEFAULT '', action TEXT NOT NULL, resource TEXT NOT NULL, request_id TEXT NOT NULL DEFAULT '', status INTEGER NOT NULL, ip_address TEXT NOT NULL DEFAULT '', created_at TIMESTAMP NOT NULL); CREATE INDEX idx_audit_events_user_id ON audit_events(user_id); CREATE INDEX idx_audit_events_action ON audit_events(action);
CREATE TABLE proof_documents (id TEXT PRIMARY KEY, activity_id TEXT NOT NULL REFERENCES conservation_activities(id), version INTEGER NOT NULL, proof_type TEXT NOT NULL, status TEXT NOT NULL, snapshot TEXT NOT NULL DEFAULT '{}', manifest_hash TEXT NOT NULL, pdf BLOB NOT NULL, qr_code BLOB NOT NULL, superseded_by_id TEXT NOT NULL DEFAULT '', created_by TEXT NOT NULL REFERENCES users(id), created_at TIMESTAMP NOT NULL); CREATE INDEX idx_proof_documents_activity_id ON proof_documents(activity_id); CREATE INDEX idx_proof_documents_status ON proof_documents(status);
CREATE TABLE credit_batches (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES conservation_projects(id), registry_issuance_id TEXT NOT NULL UNIQUE, registry_name TEXT NOT NULL, vintage INTEGER NOT NULL, serial_start TEXT NOT NULL, serial_end TEXT NOT NULL, quantity TEXT NOT NULL, available_quantity TEXT NOT NULL, status TEXT NOT NULL, adapter_mode TEXT NOT NULL, reconciled_at TIMESTAMP, created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL, CONSTRAINT idx_registry_serial UNIQUE(serial_start,serial_end)); CREATE INDEX idx_credit_batches_project_id ON credit_batches(project_id); CREATE INDEX idx_credit_batches_status ON credit_batches(status);
CREATE TABLE marketplace_listings (id TEXT PRIMARY KEY, batch_id TEXT NOT NULL UNIQUE REFERENCES credit_batches(id), project_id TEXT NOT NULL REFERENCES conservation_projects(id), product_type TEXT NOT NULL, price_per_tonne TEXT NOT NULL, currency TEXT NOT NULL, status TEXT NOT NULL, created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL); CREATE INDEX idx_marketplace_listings_status ON marketplace_listings(status);
CREATE TABLE purchases (id TEXT PRIMARY KEY, listing_id TEXT NOT NULL REFERENCES marketplace_listings(id), batch_id TEXT NOT NULL REFERENCES credit_batches(id), buyer_id TEXT NOT NULL REFERENCES users(id), quantity TEXT NOT NULL, gross_amount TEXT NOT NULL, currency TEXT NOT NULL, payment_mode TEXT NOT NULL, payment_reference TEXT NOT NULL UNIQUE, status TEXT NOT NULL, created_at TIMESTAMP NOT NULL); CREATE INDEX idx_purchases_buyer_id ON purchases(buyer_id);
CREATE TABLE custody_events (id TEXT PRIMARY KEY, batch_id TEXT NOT NULL REFERENCES credit_batches(id), purchase_id TEXT NOT NULL DEFAULT '', owner_id TEXT NOT NULL REFERENCES users(id), event_type TEXT NOT NULL, quantity TEXT NOT NULL, created_at TIMESTAMP NOT NULL); CREATE INDEX idx_custody_events_batch_id ON custody_events(batch_id); CREATE INDEX idx_custody_events_owner_id ON custody_events(owner_id);
CREATE TABLE revenue_allocations (id TEXT PRIMARY KEY, purchase_id TEXT NOT NULL REFERENCES purchases(id), project_id TEXT NOT NULL REFERENCES conservation_projects(id), recipient TEXT NOT NULL, basis_points INTEGER NOT NULL, amount TEXT NOT NULL, currency TEXT NOT NULL, created_at TIMESTAMP NOT NULL, CONSTRAINT idx_purchase_recipient UNIQUE(purchase_id,recipient)); CREATE INDEX idx_revenue_allocations_project_id ON revenue_allocations(project_id);
CREATE TABLE retirements (id TEXT PRIMARY KEY, batch_id TEXT NOT NULL REFERENCES credit_batches(id), owner_id TEXT NOT NULL REFERENCES users(id), quantity TEXT NOT NULL, status TEXT NOT NULL, registry_certificate TEXT NOT NULL DEFAULT '', transaction_ref TEXT NOT NULL DEFAULT '', object_id TEXT NOT NULL DEFAULT '', last_error TEXT NOT NULL DEFAULT '', created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL, completed_at TIMESTAMP); CREATE INDEX idx_retirements_batch_id ON retirements(batch_id); CREATE INDEX idx_retirements_status ON retirements(status);
CREATE TABLE reconciliation_cases (id TEXT PRIMARY KEY, batch_id TEXT NOT NULL REFERENCES credit_batches(id), reason TEXT NOT NULL, status TEXT NOT NULL, resolved_at TIMESTAMP, created_at TIMESTAMP NOT NULL); CREATE INDEX idx_reconciliation_cases_batch_id ON reconciliation_cases(batch_id);
CREATE TABLE financial_imports (id TEXT PRIMARY KEY, source TEXT NOT NULL, external_id TEXT NOT NULL, project_id TEXT NOT NULL REFERENCES conservation_projects(id), amount TEXT NOT NULL, currency TEXT NOT NULL, occurred_at TIMESTAMP NOT NULL, payload_hash TEXT NOT NULL, created_at TIMESTAMP NOT NULL, CONSTRAINT idx_financial_source UNIQUE(source,external_id)); CREATE INDEX idx_financial_imports_project_id ON financial_imports(project_id);
CREATE TABLE project_documents (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES conservation_projects(id), kind TEXT NOT NULL, name TEXT NOT NULL, status TEXT NOT NULL, version TEXT NOT NULL DEFAULT '', sha256 TEXT NOT NULL DEFAULT '', stored_uri TEXT NOT NULL DEFAULT '', created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL); CREATE INDEX idx_project_documents_project_id ON project_documents(project_id);
CREATE TABLE step_up_tokens (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), token_hash TEXT NOT NULL UNIQUE, action TEXT NOT NULL, used_at TIMESTAMP, expires_at TIMESTAMP NOT NULL, created_at TIMESTAMP NOT NULL); CREATE INDEX idx_step_up_tokens_user_id ON step_up_tokens(user_id); CREATE INDEX idx_step_up_tokens_expires_at ON step_up_tokens(expires_at);
CREATE TABLE satellite_passes (id UUID PRIMARY KEY, project_id UUID NOT NULL REFERENCES conservation_projects(id), activity_id UUID REFERENCES conservation_activities(id), mission TEXT NOT NULL, pass_type TEXT NOT NULL, window_start TIMESTAMPTZ NOT NULL, window_end TIMESTAMPTZ NOT NULL, acquired_at TIMESTAMPTZ, scene_id TEXT, orbit TEXT, tile TEXT, cloud_cover_pct NUMERIC(6,2), coverage_pct NUMERIC(6,2) NOT NULL, status_detail TEXT, adapter_mode TEXT NOT NULL, result_hash TEXT, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL); CREATE INDEX idx_satellite_passes_project_id ON satellite_passes(project_id); CREATE INDEX idx_satellite_passes_mission ON satellite_passes(mission);
